        <?php if ($editable) : ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" data-cb-submit><input type="hidden" name="action" value="cooms_staff"><input type="hidden" name="operation" value="<?php echo $active ? 'suspend' : 'enable'; ?>"><input type="hidden" name="staff_id" value="<?php echo esc_attr($employee->ID); ?>"><?php wp_nonce_field('cooms_staff'); ?><button type="submit" class="cb-button cb-secondary" data-busy="Mise à jour…" aria-label="<?php echo esc_attr(($active ? 'Suspendre l’accès de ' : 'Réactiver l’accès de ') . $employee->display_name); ?>"><?php echo $active ? 'Suspendre l’accès' : 'Réactiver'; ?></button></form><?php endif; ?>
        <?php if (current_user_can('edit_user', $employee->ID)) : ?><a class="cb-staff-profile" href="<?php echo esc_url(get_edit_user_link($employee->ID)); ?>">Compte WordPress<span class="screen-reader-text"> de <?php echo esc_html($employee->display_name); ?></span></a><?php endif; ?>
        </div></td></tr>
    <?php endforeach; ?></tbody></table></div>
    <footer class="cb-pagination"><span><?php echo esc_html($total . ($total > 1 ? ' comptes employés' : ' compte employé')); ?></span><nav aria-label="Pages des employés"><?php echo wp_kses_post(paginate_links(['base' => add_query_arg('paged', '%#%', admin_url('admin.php?page=cooms-bons-staff')), 'format' => '', 'current' => $page, 'total' => max(1, (int) ceil($total / 30)), 'prev_text' => 'Précédent', 'next_text' => 'Suivant'])); ?></nav></footer>
    <?php else : ?><div class="cb-empty"><h3>Aucun accès employé pour le moment</h3><p>Ajoutez la première personne ci-dessous. Le rôle vendeur est attribué automatiquement.</p></div><?php endif; ?>
</section>
